// Lista de fontes (v3): BANCO de sugestões por categoria + RADAR de descobertas.
// BANCO: categorias da Wikipedia em português (com subcategorias), as páginas mais citadas primeiro.
//        A cada execução entra outra categoria e outra "página" da lista; o filtro de repetidos garante pautas novas.
// RADAR: notícias de descobertas e curiosidades, e fontes que já vêm "curadas".
const agora = new Date();
const mm = String(agora.getMonth() + 1).padStart(2, '0');
const dd = String(agora.getDate()).padStart(2, '0');
const diaDoAno = Math.floor((agora - new Date(agora.getFullYear(), 0, 0)) / 864e5);
const rodada = diaDoAno * 4 + Math.floor(agora.getHours() / 6); // muda a cada execução (4x ao dia)

// [categoria da Wikipedia, quantas páginas de 20 artigos ela tem que valem a pena]
const BANCO = {
  'Topografia e relevo': [['Serras do Brasil', 5], ['Picos do Brasil', 5], ['Chapadas do Brasil', 5], ['Cavernas do Brasil', 3], ['Planaltos do Brasil', 1], ['Dunas do Brasil', 1]],
  'Clima': [['Clima do Brasil', 5], ['Desastres naturais no Brasil', 5], ['Enchentes no Brasil', 2], ['Tornados no Brasil', 1], ['Secas no Brasil', 1]],
  'Geografia': [['Rios do Brasil', 5], ['Hidrografia do Brasil', 5], ['Lagoas do Brasil', 5], ['Arquipélagos do Brasil', 5], ['Ilhas do Brasil', 5]],
  'Sociologia': [['Lendas do Brasil', 4], ['Quilombos', 5], ['Favelas do Brasil', 5], ['Línguas do Brasil', 5]],
  'História do Brasil': [['Sítios arqueológicos do Brasil', 4], ['Revoltas no Brasil', 5], ['Brasil Colônia', 2], ['Império do Brasil', 5], ['Escravidão no Brasil', 5]],
};
const POR_PAGINA = 20;
const wiki = (busca, offset) =>
  'https://pt.wikipedia.org/w/api.php?action=query&format=json&formatversion=2' +
  '&generator=search&gsrnamespace=0&gsrsort=incoming_links_desc' +
  `&gsrlimit=${POR_PAGINA}&gsroffset=${offset}&gsrsearch=${encodeURIComponent('deepcat:"' + busca + '"')}` +
  '&prop=extracts|pageimages|langlinks&exintro=1&explaintext=1&exsentences=2&exlimit=max' +
  '&piprop=original|name&lllang=en&lllimit=max';

// Reserva: se a busca da Wikipedia estiver ocupada ("too busy"), usa a lista simples da categoria, começando por uma letra que muda a cada rodada.
const LETRAS = 'ABCDEFGIJLMNOPRSTV';
const reserva = busca =>
  'https://pt.wikipedia.org/w/api.php?action=query&format=json&formatversion=2' +
  `&generator=categorymembers&gcmtitle=${encodeURIComponent('Categoria:' + busca)}&gcmtype=page&gcmlimit=${POR_PAGINA}` +
  `&gcmstartsortkeyprefix=${LETRAS[rodada % LETRAS.length]}` +
  '&prop=extracts|pageimages|langlinks&exintro=1&explaintext=1&exsentences=2&exlimit=max' +
  '&piprop=original|name&lllang=en&lllimit=max';

const fontes = [];
const reservas = [];
for (const [categoria, buscas] of Object.entries(BANCO)) {
  const [busca, paginas] = buscas[rodada % buscas.length];
  const offset = (Math.floor(rodada / buscas.length) % paginas) * POR_PAGINA;
  fontes.push({ fonte: `Wikipedia: ${busca}`, categoria, idioma: 'pt', tipo: 'banco', exigeBrasil: true, curada: true, url: wiki(busca, offset) });
  reservas.push({ fonte: `Wikipedia (reserva): ${busca}`, categoria, idioma: 'pt', tipo: 'banco', reserva: true, exigeBrasil: true, curada: true, url: reserva(busca) });
}
fontes.push(...reservas); // só são usadas quando a busca principal da categoria falha

// RADAR de descobertas e curiosidades
const gn = (q, hl, gl, ceid) =>
  `https://news.google.com/rss/search?q=${encodeURIComponent(q)}&hl=${hl}&gl=${gl}&ceid=${ceid}`;
fontes.push(
  { fonte: 'Descobertas EN', categoria: '', idioma: 'en', tipo: 'radar', exigeBrasil: true, curada: false,
    url: gn('Brazil (discovered OR discover OR "new species" OR fossil OR archaeologists OR mystery OR ancient OR "never seen") -"rare earth" -deal -election -football', 'en-US', 'US', 'US:en') },
  { fonte: 'Descobertas PT', categoria: '', idioma: 'pt', tipo: 'radar', exigeBrasil: true, curada: false,
    url: gn('Brasil (descobrem OR descoberta OR "nova espécie" OR fóssil OR arqueólogos OR mistério OR "nunca antes") -futebol -eleição', 'pt-BR', 'BR', 'BR:pt-419') },
  { fonte: 'Descobertas ES', categoria: '', idioma: 'es', tipo: 'radar', exigeBrasil: true, curada: false,
    url: gn('Brasil (descubren OR hallazgo OR "nueva especie" OR fósil OR arqueólogos OR misterio) -fútbol -elecciones', 'es-419', 'AR', 'AR:es-419') },
  { fonte: 'Sociedade em dados PT', categoria: 'Sociologia', idioma: 'pt', tipo: 'radar', exigeBrasil: true, curada: true,
    url: gn('brasileiros (IBGE OR censo OR pesquisa) (revela OR curiosidade OR "pela primeira vez" OR maioria) -eleição -futebol', 'pt-BR', 'BR', 'BR:pt-419') },
  { fonte: 'Clima e fenômenos PT', categoria: 'Clima', idioma: 'pt', tipo: 'radar', exigeBrasil: true, curada: false,
    url: gn('Brasil (fenômeno OR "recorde de calor" OR geada OR neve OR ciclone OR tornado OR granizo) -futebol', 'pt-BR', 'BR', 'BR:pt-419') },
  { fonte: 'Reddit TIL', categoria: '', idioma: 'en', tipo: 'radar', exigeBrasil: true, curada: true,
    url: 'https://www.reddit.com/r/todayilearned/search.rss?q=brazil&restrict_sr=1&sort=top&t=month' },
  { fonte: 'Wikipedia: você sabia', categoria: '', idioma: 'en', tipo: 'radar', exigeBrasil: true, curada: true,
    url: 'https://en.wikipedia.org/w/api.php?action=parse&page=Template:Did_you_know&prop=text&format=json&formatversion=2' },
  { fonte: 'Wikipedia: hoje na história', categoria: 'História do Brasil', idioma: 'en', tipo: 'radar', exigeBrasil: true, curada: true,
    url: `https://en.wikipedia.org/api/rest_v1/feed/onthisday/events/${mm}/${dd}` },
  { fonte: 'NASA Earth', categoria: 'Geografia', idioma: 'en', tipo: 'radar', exigeBrasil: true, curada: true,
    url: 'https://science.nasa.gov/feed/?science_org=19791,22453' },
  { fonte: 'Mongabay (natureza)', categoria: 'Geografia', idioma: 'en', tipo: 'radar', exigeBrasil: true, curada: false,
    url: 'https://news.mongabay.com/feed/' },
  { fonte: 'Concorrente: Geography By Geoff', categoria: '', idioma: 'en', tipo: 'concorrente', exigeBrasil: true, curada: true,
    url: 'https://www.youtube.com/feeds/videos.xml?channel_id=UC7-Z34pbJ0ZAOJRmUCEz0Cg' },
);

return fontes.map(f => ({ json: f }));

// v3: monta o BANCO de sugestões por categoria (Wikipedia) e o RADAR de descobertas (notícias curadas).
const fontes = $('Lista de fontes').all().map(i => i.json);
const respostas = $input.all();
const memoria = $getWorkflowStaticData('global'); // links já vistos entre execuções (só vale com o workflow publicado)
memoria.vistos = memoria.vistos || {};
const agora = new Date().toISOString();

const limpar = s => (s || '')
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;|&apos;|&#039;/g, "'").replace(/&nbsp;/g, ' ')
  .replace(/\s+/g, ' ').trim();
const tag = (bloco, nome) => {
  const m = bloco.match(new RegExp(`<${nome}[^>]*>([\\s\\S]*?)</${nome}>`, 'i'));
  return m ? limpar(m[1]) : '';
};

const BRASIL = /brasil|brazil|brasileir|brasile|amaz[oô]n|rio de janeiro|s[aã]o paulo|bras[ií]lia|pantanal|tiet[eê]|igua[cç]u|nordeste|manaus|cerrado|caatinga|mata atl[aâ]ntica|atlantic forest|fernando de noronha|len[cç][oó]is|\bacre\b|alagoas|amap[aá]|bahia|cear[aá]|esp[ií]rito santo|goi[aá]s|maranh[aã]o|mato grosso|minas gerais|\bpar[aá]\b|para[ií]ba|paran[aá]|pernambuco|piau[ií]|rio grande do (norte|sul)|rond[oô]nia|roraima|santa catarina|sergipe|tocantins|tupi|guaran/i;
const DESCOBERTA = /descob|discover|cientist|scientist|cient[ií]fic|pesquisador|researcher|investigador|esp[eé]cie|species|f[oó]ss|fossil|arque[oó]log|archaeolog|antig|ancient|mist[eé]r|myster|\braro\b|\brare\b|in[eé]dit|hallazgo|estranh|weird|strange|incomum|unusual|curios|segredo|secret|enigma/i;
const GEO = /\brio\b|river|\br[ií]o\b|ilha|island|isla|serra|montanh|mountain|floresta|forest|caverna|cave|cachoeira|waterfall|catarata|lago|lake|duna|dune|vulc|volcan|fronteira|border|mapa|\bmap\b|sat[eé]lite|satellite|meteor/i;
const SUPER = /maior|menor|largest|biggest|smallest|[uú]nic[oa]|unique|\bonly\b|oldest|mais antig|deepest|highest|mais alt|longest|mais long/i;
const PORQUE = /por que|why|por qu[eé]/i;
// notícia comum que não vira pauta: política, economia, esporte, crime, eventos
const NEGATIVOS = /elei[cç]|election|presiden|lula|bolsonaro|senado|senate|congresso|congress|\bstf\b|minist[eé]rio|ministry|governo|government|tarif|soja|soybean|mercado|market|bolsa|stock|d[oó]lar|juros|infla[cç]|\bpib\b|\bgdp\b|empresa|company|a[cç][oõ]es|investi|copa do mundo|world cup|sele[cç][aã]o|advers[aá]ri|futebol|football|soccer|escala[cç]|oitavas|campeonato|\bgol\b|bbb|novela|reality|celebridad|hor[oó]scopo|avenida brasil|\bmort[eo]s?\b|assassin|pol[ií]cia|police|\bpms?\b|tiro|balead|pres[oa]s?\b|pris[aã]o|crime|tr[aá]fico|shooting|killed|festival|premia[cç]|award|semin[aá]rio|webinar|show\b|rare earth|terras raras|tierras raras|\bdeal\b|acordo|contrato|drug|medicament|vacina|doen[cç]a|disease|democracia|democracy|sindicat|ranking|influentes|f[uú]tbol|entrenador|t[eé]cnico|jugador|player|coach|hinchas|libertadores|sudamericana|plantel|fichaje|refuerzo|famos[oa]s?\b|filh[ao] de|selecci[oó]n|convoca|\bdt\b|boca juniors|river plate|arruabarrena|gin[aá]stica|mundial de|ballet|bal[eé]\b|espet[aá]culo|turn[eê]|exporta|tonelad|cadena|cadeia de lojas|loja/i;
// páginas da Wikipedia que não viram pauta: listas, pessoas, cidades, clubes, órgãos, obras
// (usa (?:^|[\s,]) em vez de \b porque \b não funciona antes de "é" no JavaScript)
const NAO_BANCO_TITULO = /^lista|desambigua|clube|club\b|futebol|foot ?ball|esporte clube|atl[eé]tico|partido|ag[eê]ncia|minist[eé]rio|universidade|faculdade|instituto|banco |est[aá]dio|telenovela|^rede |^\d{3,4} no brasil|^\d{3,4}$|\((telenovela|filme|livro|[aá]lbum|can[cç][aã]o|banda)|^edif[ií]cio|^samb[oó]dromo|^escola de samba|^aeroporto|^hospital|^shopping|^ponte |cidade universit/i;
const NAO_BANCO_RESUMO = /(?:^|[\s,])(é|foi|são|era|foram) (um|uma|o|a|os|as) ([a-zà-ú]+ )?(munic[ií]pio|distrito|empresa|concession[aá]ria|est[aá]dio|clube|rodovia|autarquia|[oó]rg[aã]o|programa|edif[ií]cio|shopping|telenovela|novela|miniss[eé]rie|s[eé]rie|filme|romance|livro|[aá]lbum|can[cç][aã]o|emissora|rede|organiza[cç][aã]o|institui[cç][aã]o|funda[cç][aã]o|departamento|faculdade|universidade|escola|time|equipe|associa[cç][aã]o|companhia|jornal|peri[oó]dico|revista|banda|grupo musical|esp[eé]cie|g[eê]nero|vila|povoado)(?![a-zà-ú])/i;
const PESSOA = /(?:^|[\s,])(foi|é|era) (um|uma|o|a) ([a-zà-ú]+ )?(pol[ií]tic|militar|escritor|cantor|ator|atriz|jogador|empres[aá]ri|advogad|m[eé]dic|padre|bispo|historiador|soci[oó]log|ge[oó]graf|jornalista|poeta|compositor|pintor|sertanista|explorador|engenheir|economista|professor|imperador|rei\b|rainha|pr[ií]ncipe|princesa|nobre|pesquisador|cientista|ativista|arquitet|fot[oó]graf|antrop[oó]log|climatolog|meteorolog|f[ií]sic|qu[ií]mic|bi[oó]log|bot[aâ]nic|naturalista|navegador|cors[aá]rio|pirata|governador|prefeito|deputad|senador|bandeirante|l[ií]der|guerreir|monarca|estadista|diplomata|magistrad|juiz|religios|mission[aá]ri|jesu[ií]ta|dan[cç]arin|cirandeir|artista|m[uú]sic|cineasta|escultor|fil[oó]sof|ensa[ií]sta|romancista|dramaturgo|sacerdote|frade|santo|beato)/i;
const NASCIMENTO = /\((?:[A-ZÀ-Ú][^(),]*),\s*(?:ca?\.\s*)?(?:\d{1,2}º? de [a-zç]+ de )?\d{3,4}/; // "(Cidade, 2 de dezembro de 1825" = biografia

// classifica notícias do radar quando a fonte não define a categoria
const CATEGORIAS = [
  ['Topografia e relevo', /serra|montanh|mountain|pico\b|peak|planalto|plateau|chapada|c[aâ]nion|canyon|relevo|altitude|escarpa|dun[ae]s?|dune/i],
  ['Clima', /clima|climate|chuva|rain|seca|drought|calor|heat|frio|cold|neve|snow|geada|frost|ciclone|cyclone|tornado|tempestade|storm|el ni[nñ]o|temperatura/i],
  ['História do Brasil', /hist[oó]ri|history|imp[eé]rio|empire|col[oô]ni|colonial|escrav|slaver|revolt|guerra|war\b|independ|s[eé]culo|century|\b1[5-9]\d\d\b|arque[oó]log|archaeolog|ancient|antig/i],
  ['Sociologia', /popula[cç]|population|censo|census|migra|imigra|immigra|favela|quilomb|ind[ií]gen|indigenous|desigual|inequal|idioma|language|sotaque|accent|cultura|culture|religi|sociedad|society|cidade|city/i],
  ['Geografia', /\brio\b|river|ilha|island|fronteira|border|bacia|basin|litoral|coast|lago|lake|lagoa|amaz[oô]n|cerrado|pantanal|caatinga|floresta|forest|mapa|\bmap\b|sat[eé]lite|satellite/i],
];
const classificar = t => { for (const [c, r] of CATEGORIAS) if (r.test(t)) return c; return 'Descobertas e curiosidades'; };

const MAX_BANCO_POR_CATEGORIA = 2; // por execução: 5 categorias x 2 = 10 sugestões novas no banco (40 por dia)
const MAX_RADAR_POR_FONTE = 4;

const saida = [];
const bancoOk = {}; // categorias cuja busca principal respondeu (aí a reserva é ignorada)
const titulosDaRodada = new Set(); // a mesma notícia em vários veículos entra uma vez só
respostas.forEach((resp, i) => {
  const f = fontes[i] || {};
  if (f.reserva && bancoOk[f.categoria]) return;
  const d = resp.json.data;
  const corpo = typeof d === 'string' ? d : (d ? JSON.stringify(d) : '');
  if (!corpo) return; // fonte fora do ar: segue com as outras

  let itens = [];
  if (corpo.trim().startsWith('{')) {
    let j;
    try { j = JSON.parse(corpo); } catch (e) { return; }
    if (j.query && Array.isArray(j.query.pages)) { // Wikipedia: busca do banco
      if (f.tipo === 'banco' && !f.reserva && j.query.pages.length) bancoOk[f.categoria] = true;
      itens = j.query.pages
        .sort((a, b) => (a.index || 0) - (b.index || 0))
        .map(p => {
          const en = (p.langlinks || []).find(l => l.lang === 'en');
          const tituloEn = en ? (en.title || en['*'] || '') : '';
          return {
            titulo: p.title,
            link: 'https://pt.wikipedia.org/wiki/' + encodeURIComponent(p.title.replace(/ /g, '_')),
            resumo: (p.extract || '').slice(0, 400),
            imagem: (p.original && p.original.source) || '',
            arquivoImagem: p.pageimage ? 'https://commons.wikimedia.org/wiki/File:' + encodeURIComponent(p.pageimage) : '',
            emIngles: tituloEn ? 'https://en.wikipedia.org/wiki/' + encodeURIComponent(tituloEn.replace(/ /g, '_')) : 'não existe (lacuna)',
            publicado: '',
          };
        });
    } else if (j.parse && j.parse.text) { // Wikipedia "Did you know"
      const html = typeof j.parse.text === 'string' ? j.parse.text : (j.parse.text['*'] || '');
      itens = (html.match(/<li[\s>][\s\S]*?<\/li>/gi) || []).map(li => {
        const m = li.match(/href="(\/wiki\/[^"#]+)"/i);
        return { titulo: limpar(li), link: m ? 'https://en.wikipedia.org' + m[1] : '', resumo: '', imagem: '', publicado: agora.slice(0, 10) };
      }).filter(x => x.titulo.startsWith('...'));
    } else if (Array.isArray(j.events)) { // Wikipedia "hoje na história"
      itens = j.events.map(e => ({
        titulo: `${e.year}: ${e.text}`,
        link: (e.pages && e.pages[0] && e.pages[0].content_urls && e.pages[0].content_urls.desktop.page) || '',
        resumo: '', imagem: '', publicado: String(e.year),
      }));
    }
  } else { // RSS (<item>) ou Atom (<entry>)
    const blocos = corpo.match(/<item[\s>][\s\S]*?<\/item>/gi) || corpo.match(/<entry[\s>][\s\S]*?<\/entry>/gi) || [];
    const googleNews = /news\.google\./.test(f.url || '');
    itens = blocos.map(b => {
      let link = tag(b, 'link');
      if (!link) { const m = b.match(/<link[^>]*href="([^"]+)"/i); link = m ? m[1] : ''; }
      let titulo = tag(b, 'title');
      let veiculo = '';
      if (googleNews) { // no Google News a descrição só repete o título + nome do veículo ("CNN Brasil" enganava o filtro)
        const m = titulo.match(/^(.*\S)\s+-\s+([^-]+)$/);
        if (m) { titulo = m[1]; veiculo = m[2].trim(); }
      }
      return { titulo, veiculo, link, resumo: googleNews ? '' : tag(b, 'description').slice(0, 400), imagem: '',
        publicado: tag(b, 'pubDate') || tag(b, 'published') || tag(b, 'updated') };
    });
  }

  let aceitos = 0;
  const limite = f.tipo === 'banco' ? MAX_BANCO_POR_CATEGORIA : MAX_RADAR_POR_FONTE;
  for (const it of itens.slice(0, 50)) {
    if (aceitos >= limite) break;
    if (!it.link || !it.titulo) continue;
    const texto = `${it.titulo} ${it.resumo || ''}`;
    const falaDoBrasil = BRASIL.test(texto);
    if (f.exigeBrasil && !falaDoBrasil) continue;
    let pontos;
    if (f.tipo === 'banco') {
      const resumo = it.resumo || '';
      if (NAO_BANCO_TITULO.test(it.titulo) || NASCIMENTO.test(resumo) || PESSOA.test(resumo)
        || NAO_BANCO_RESUMO.test(resumo.split('. ')[0])) continue;
      pontos = 3 + (SUPER.test(texto) ? 1 : 0) + (DESCOBERTA.test(texto) ? 1 : 0) + (PORQUE.test(texto) ? 1 : 0) + (it.imagem ? 1 : 0);
    } else {
      if (f.tipo !== 'concorrente' && NEGATIVOS.test(it.titulo)) continue;
      pontos = (DESCOBERTA.test(texto) ? 2 : 0) + (GEO.test(texto) ? 1 : 0) + (SUPER.test(texto) ? 1 : 0)
        + (PORQUE.test(texto) ? 1 : 0) + (falaDoBrasil ? 1 : 0) + (f.curada ? 2 : 0);
      if (f.tipo !== 'concorrente' && pontos < 3) continue; // notícia precisa de descoberta + Brasil
    }
    const chaveTitulo = it.titulo.toLowerCase().replace(/[^a-z0-9à-ú]/g, '').slice(0, 60);
    if (memoria.vistos[it.link] || titulosDaRodada.has(chaveTitulo)) continue;
    titulosDaRodada.add(chaveTitulo);
    memoria.vistos[it.link] = agora;
    aceitos++;
    saida.push({
      data_coleta: agora,
      categoria: f.categoria || classificar(texto),
      tipo: f.tipo, fonte: it.veiculo ? `${f.fonte} (${it.veiculo})` : f.fonte, idioma: f.idioma, pontuacao: pontos,
      titulo: it.titulo.slice(0, 250), resumo: it.resumo || '', link: it.link, em_ingles: it.emIngles || '',
      imagem: it.imagem || '', publicado: it.publicado || '', status: 'nova', fato_checado: '', fonte_primaria: '',
      licenca_imagem: it.arquivoImagem ? 'conferir: ' + it.arquivoImagem : '',
    });
  }
});

// mantém só os 8.000 links mais recentes na memória
const chaves = Object.keys(memoria.vistos);
if (chaves.length > 8000) {
  chaves.sort((a, b) => (memoria.vistos[a] < memoria.vistos[b] ? -1 : 1))
    .slice(0, chaves.length - 8000)
    .forEach(k => delete memoria.vistos[k]);
}

// banco primeiro, depois radar; dentro de cada um, maior pontuação primeiro
saida.sort((a, b) => (a.tipo === 'banco' ? 0 : 1) - (b.tipo === 'banco' ? 0 : 1) || b.pontuacao - a.pontuacao);
return saida.slice(0, 40).map(j => ({ json: j }));

// Prepara as consultas de enriquecimento das sugestões do banco (Wikipedia):
// 1) links externos do artigo, para sugerir a fonte primária;
// 2) licença e autor da imagem principal (uma consulta para até 50 imagens).
const linhas = $input.all().map(i => i.json);
const API = 'https://pt.wikipedia.org/w/api.php?action=query&format=json&formatversion=2';
const pedidos = [];
const arquivos = [];

linhas.forEach((l, i) => {
  if (l.tipo !== 'banco') return;
  const titulo = decodeURIComponent((l.link || '').split('/wiki/')[1] || '').replace(/_/g, ' ');
  if (titulo) pedidos.push({ tipo: 'fontes', linha: i, url: `${API}&prop=extlinks&ellimit=max&titles=${encodeURIComponent(titulo)}` });
  const m = (l.licenca_imagem || '').match(/File:(.+)$/);
  if (m) arquivos.push('File:' + decodeURIComponent(m[1]));
});

for (let k = 0; k < arquivos.length; k += 50) {
  pedidos.push({ tipo: 'licenca', linha: -1,
    url: `${API}&prop=imageinfo&iiprop=extmetadata|url&iiextmetadatafilter=LicenseShortName|Artist|UsageTerms` +
      `&titles=${encodeURIComponent(arquivos.slice(k, k + 50).join('|'))}` });
}

// sem sugestões do banco: uma consulta leve só para as linhas do radar seguirem até a planilha
if (!pedidos.length) pedidos.push({ tipo: 'nada', linha: -1, url: `${API}&meta=siteinfo` });

return pedidos.map(p => ({ json: p }));

// Junta o enriquecimento nas linhas: fonte primária sugerida e licença/autor da imagem.
const linhas = $('Ler, filtrar e pontuar').all().map(i => ({ ...i.json }));
const pedidos = $('Preparar enriquecimento').all().map(i => i.json);
const respostas = $input.all();

// sites oficiais, universidades e periódicos científicos
const CONFIAVEL = /\.gov\.br|\.leg\.br|\.jus\.br|\.mil\.br|\.edu\.br|\.ufrj\.br|\.usp\.br|unicamp\.br|unesp\.br|ufmg\.br|ufpe\.br|ufba\.br|ibge|icmbio|inpe\.br|embrapa|cemaden|inmet|iphan|fiocruz|cprm|scielo|doi\.org|jstor\.org|nature\.com|science\.org|sciencedirect|springer|wiley\.com|cambridge\.org|academic\.oup|tandfonline|plos|nasa\.gov|noaa\.gov|usgs\.gov|unesco\.org|wmo\.int|bndigital|arquivonacional|biodiversitylibrary|museu/i;
// links de busca que a Wikipedia coloca em todo artigo ("Procurar fontes") não contam
const EXCLUIR = /[?&](q|query|search|busca|term)=|wikipedialibrary|periodicos\.capes|google\.|worldcat|viaf\.org/i;
const texto = s => String(s || '').replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"')
  .replace(/&#0?39;/g, "'").replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
const chave = s => String(s || '').replace(/^[^:]+:/, '').replace(/_/g, ' ').trim().toLowerCase();
const lerJson = r => {
  const d = r && r.json && r.json.data;
  try { return typeof d === 'string' ? JSON.parse(d) : (d || {}); } catch (e) { return {}; }
};

const licencas = {};
pedidos.forEach((p, k) => {
  const j = lerJson(respostas[k]);
  const paginas = (j.query && j.query.pages) || [];

  if (p.tipo === 'fontes' && linhas[p.linha]) {
    if (!j.query) return; // consulta falhou: deixa em branco
    const links = ((paginas[0] && paginas[0].extlinks) || []).map(e => e.url || e['*'] || '');
    const hosts = new Set();
    const boas = [];
    for (const bruto of links) {
      const u = bruto.startsWith('//') ? 'https:' + bruto : bruto;
      if (!/^https?:/.test(u) || EXCLUIR.test(u) || !CONFIAVEL.test(u)) continue;
      const host = (u.match(/^https?:\/\/(?:web\.archive\.org\/web\/[^/]+\/)?(?:https?:\/\/)?([^/:]+)/i) || [])[1] || u;
      const partes = host.toLowerCase().split('.');
      const dominio = partes.slice(/\.(gov|edu|org|com|leg|jus|mil|net)\.br$/i.test(host) ? -3 : -2).join('.');
      if (hosts.has(dominio)) continue;
      hosts.add(dominio);
      boas.push(u);
      if (boas.length === 2) break;
    }
    linhas[p.linha].fonte_primaria = boas.length ? boas.join(' | ') : 'nenhuma fonte oficial no artigo';
  }

  if (p.tipo === 'licenca') {
    for (const pg of paginas) {
      const info = pg.imageinfo && pg.imageinfo[0];
      if (!info) continue;
      const m = info.extmetadata || {};
      const lic = texto(m.LicenseShortName && m.LicenseShortName.value) || texto(m.UsageTerms && m.UsageTerms.value) || 'licença não informada';
      const autor = texto(m.Artist && m.Artist.value).slice(0, 120);
      licencas[chave(pg.title)] = `${lic}${autor ? ' | autor: ' + autor : ''} | ${info.descriptionurl || ''}`;
    }
  }
});

for (const l of linhas) {
  const m = (l.licenca_imagem || '').match(/File:(.+)$/);
  if (m && licencas[chave(decodeURIComponent(m[1]))]) l.licenca_imagem = licencas[chave(decodeURIComponent(m[1]))];
}

return linhas.map(l => ({ json: l }));

// Potencial viral (0 a 10) de cada pauta, por regras simples (sem IA). A partir de 5 = vale alerta.
// Lógica: o que costuma prender em Shorts de curiosidade = algo que o público de fora não conhece
// + superlativo + mistério/perigo + descoberta + imagem pronta + fonte para checar.
const SUPER = /maior|menor|(?:^|[\s(])[uú]nic[oa]s?(?![a-zà-ú])|mais antig|mais alt|mais long|mais profund|mais quente|mais fri|recorde|nunca|primeir[oa]s? (d|n)[oa]s?\b|largest|biggest|smallest|\bonly\b|oldest|highest|longest|deepest|hottest|record|\bmost\b|\bfirst\b|never/i;
const MISTERIO = /mist[eé]ri|enigma|estranh|bizarr|lenda|assombr|maldi[cç]|proibid|perig|mortal|venen|serpente|cobra|jararaca|tubar|monstro|gigante|desaparec|abandonad|fantasma|segredo|escondid|perdid|isolad|myster|weird|strange|bizarre|legend|haunt|curse|forbidden|danger|deadly|venom|snake|giant|vanish|abandoned|ghost|secret|hidden|lost|isolated/i;
const DESCOBERTA = /descob|discover|nova esp[eé]cie|new species|f[oó]ssil|fossil|arque[oó]log|archaeolog|ancient|pr[eé]-hist|dinossaur|dinosaur/i;
const PORQUE = /por que|why|por qu[eé]/i;
const CURADA = /Reddit TIL|você sabia|NASA Earth/;

const linhas = $input.all().map(i => ({ ...i.json }));
for (const l of linhas) {
  const t = `${l.titulo || ''} ${l.resumo || ''}`;
  let s = 0;
  if (String(l.em_ingles || '').includes('lacuna')) s += 3; // ninguém contou isso em inglês ainda
  if (SUPER.test(t)) s += 2;
  if (MISTERIO.test(t)) s += 2;
  if (DESCOBERTA.test(t)) s += 2;
  if (PORQUE.test(t)) s += 1;
  if (l.imagem) s += 1;
  if (CURADA.test(l.fonte || '')) s += 2; // já foi escolhida por pessoas como curiosidade
  if (l.fonte_primaria && !String(l.fonte_primaria).startsWith('nenhuma')) s += 1; // dá para checar
  l.potencial_viral = Math.min(10, s);
}

// maior potencial primeiro
linhas.sort((a, b) => b.potencial_viral - a.potencial_viral || b.pontuacao - a.pontuacao);
return linhas.map(l => ({ json: l }));

// Junta as pautas com potencial viral alto numa mensagem só (pronta para WhatsApp ou e-mail).
// Sem nenhuma pauta acima do corte, não sai nada e nada é enviado.
const CORTE = 5;
const top = $input.all().map(i => i.json).filter(l => l.potencial_viral >= CORTE);
if (!top.length) return [];

const itens = top.slice(0, 5).map((l, k) =>
  `${k + 1}. *${l.titulo}* (${l.potencial_viral}/10)\n` +
  `   ${l.categoria}${String(l.em_ingles).includes('lacuna') ? ' · sem artigo em inglês' : ''}\n` +
  `   ${l.link}`);
const mensagem = `🔥 Radar de pautas: ${top.length} com potencial viral\n\n${itens.join('\n\n')}` +
  (top.length > 5 ? `\n\n+${top.length - 5} na planilha` : '');

return [{ json: { mensagem, total: top.length } }];
